window.AUTH=window.AUTH||{};window.AUTH["23-1270"]={"d":"23-1270","id":"2024/23-1270","n":"Riley v. Bondi","briefs":[{"k":"petitioner","label":"Brief of petitioner Pierre Riley","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/336575/20250103170437724_Brief%20for%20Petitioner.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent Merrick B. Garland, Attorney General in support of petitioner","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/336571/20250103164128736_23-1270tsUnitedStates.pdf","side":"res","n":115},{"k":"reply","label":"Reply of petitioner Pierre Yassue Nashun Riley","date":"2025-03-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/352183/20250314155027985_Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r58_5h25.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"not in a vacuum, but with reference to the statutory context, ‘structure, history, and purpose.’","cite":"573 U.S. 169, 179"}]},{"t":"case","label":"Adenariwo v. Federal Maritime Comm’n","cite":"808 F.3d 74","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/808/74/","by":{"0":"50"},"q":[{"src":"brief","b":0,"text":"is determined not ‘by the administrative agency’s characterization of its action, but rather by a realistic assessment of the nature and effect of the order sought to be reviewed,’","cite":"808 F.3d 74, 78"}]},{"t":"case","label":"Alonso-Juarez v. Garland","cite":"80 F.4th 1039","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/1039/","by":{"0":"18, 51, 52","1":"24, 35"},"q":[{"src":"brief","b":0,"text":"to establish a system of holding petitions for review in abeyance for years at a time.","cite":"80 F.4th at 1053"},{"src":"brief","b":1,"text":"It would lead to an increase in filings, as petitioners would inevitably have to file a petition for review to preserve the possibility of judicial review, even when unsure if they would need to, or even choose to, challenge the decision in the future.","cite":"80 F.4th 1039, 1053"}]},{"t":"case","label":"American Hospital Assn. v. Becerra","cite":"596 U.S. 724","y":2022,"id":"2021/20-1114","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"[t]his Court has long recognized a ‘strong presumption’ in favor of judicial review of final agency action.","cite":"596 U.S. 724, 733"}]},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"by":{"0":"17, 22, 24, 27","1":"23"},"q":[{"src":"brief","b":1,"text":"predates [the Court’s] cases, starting principally with","cite":"546 U.S. 500"},{"src":"argument","who":"Justice Jackson","text":"And I thought Santos -- Zacaria pointed out that Stone was a drive-by jurisdictional holding, it was pre-Arbaugh, it really didn't do the -- the work that was necessary to establish a -- binding holding related to the jurisdictional provision."},{"src":"argument","who":"Mr. Hammer","text":"I understand that to be a -- a reference to not applying Arbaugh's clear statement rule. You have the \"was not central\" comment, and I think that is a reflection of the government's argument in Santos-Zacaria about the entirety of the INA's --"},{"src":"argument","who":"Mr. Hammer","text":"It was the analogy that supported the Court's ultimate conclusion that the deadline was jurisdictional and engaged in this extensive analysis, comparing the deadline to file a notice of appeal from a final order of deportation to the time to notice of an appeal from a district court judgment, which as you point out this Court has recognized as jurisdictional, both before and after Arbaugh."}]},{"t":"case","label":"Argueta-Hernandez v. Garland","cite":"87 F.4th 698","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/87/698/","by":{"0":"41","1":"35"},"q":[{"src":"brief","b":1,"text":"disastrous consequences on the immigration and judicial systems.","cite":"87 F.4th 698, 706"}]},{"t":"case","label":"Army Corps of Engineers v. Hawkes Co.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"by":{"0":"31"}},{"t":"case","label":"Arostegui-Maldonado v. Garland","cite":"75 F.4th 1132","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/75/1132/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"Holding that a reinstated removal order is final for purposes of an IJ’s consideration of detention does not answer whether it is final for purposes of circuit court review of the outcome of withholding-only proceedings.","cite":"75 F.4th 1132, 1143"}]},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"by":{"0":"30"}},{"t":"case","label":"Boechler, P.C. v. Commissioner of Internal Revenue","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"by":{"0":"17, 18, 26, 27","2":"1, 11"},"q":[{"src":"brief","b":0,"text":"Congress need not ‘incant magic words,’ . . . but the ‘traditional tools of statutory construction must plainly show that Congress imbued a procedural bar with jurisdictional consequences.’","cite":"596 U.S. 199, 203"}]},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"0":"25","1":"13, 19","2":"8, 9"}},{"t":"case","label":"Calcano-Martinez v. INS","cite":"533 U.S. 348","y":2001,"id":"2000/00-1011","sc":1,"by":{"0":"26","1":"2"}},{"t":"case","label":"Chicago & Southern Air Lines v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"30, 34"}},{"t":"case","label":"Chupina v. Holder","cite":"570 F.3d 99","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/99/","by":{"0":"43","1":"38, 39"}},{"t":"case","label":"(iv) Cases—Continued Cyan v. Beaver County Employees Retirement Fund","cite":"583 U.S. 416","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/416/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Delgado-Reynua v. Gonzales","cite":"450 F.3d 596","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/596/","by":{"0":"32"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"by":{"0":"25"}},{"t":"case","label":"Eke v. Mukasey","cite":"512 F.3d 372","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/512/372/","by":{"0":"9","1":"41"}},{"t":"case","label":"F.J.A.P. v. Garland","cite":"94 F.4th 620","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/94/620/","by":{"0":"33, 42, 44, 50","1":"31, 33, 35, 37, 39, 48"},"q":[{"src":"brief","b":0,"text":"although a CAT order does not determine whether a noncitizen can be removed, it does determine where that noncitizen can be sent.","cite":"94 F.4th 620, 634"},{"src":"brief","b":0,"text":"hesitate before finding that Congress vested the executive branch with the authority to shape the scope of . . . review so drastically.","cite":"94 F.4th at 637, n.10"},{"src":"brief","b":1,"text":"do[] not determine whether a noncitizen can be removed, [they] do[] determine where that noncitizen can be sent.","cite":"94 F.4th at 634"}]},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"In statutory interpretation disputes, a court’s proper starting point lies in a careful examination of the ordinary meaning and structure of the law itself.","cite":"588 U.S. 427, 436"}]},{"t":"case","label":"Fort Bend County v. Davis","cite":"587 U.S. 541","y":2019,"id":"2018/18-525","sc":1,"by":{"0":"20, 21","1":"40"},"q":[{"src":"brief","b":0,"text":"[A] nonjurisdictional provision does not metamorphose into a jurisdictional limitation by cross-referencing a jurisdictional provision,","cite":"587 U.S. 541, 551, n.8"},{"src":"brief","b":0,"text":"stated it would treat a requirement as ‘jurisdictional’ when ‘a long line of [Supreme] Cour[t] decisions left undisturbed by Congress’ attached a jurisdictional label to the prescription.","cite":"587 U.S. at 548"},{"src":"brief","b":1,"text":"the classes of cases a court may entertain.","cite":"587 U.S. 541, 548"}]},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"the ruling of a subordinate official.","cite":"505 U.S. 788, 797"}]},{"t":"case","label":"Fritsch v. ICC","cite":"59 F.3d 248","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/248/","by":{"0":"50"}},{"t":"case","label":"Garland v. Cargill","cite":"602 U.S. 406","y":2024,"id":"2023/22-976","sc":1,"by":{"0":"39"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"0":"20","1":"21"}},{"t":"case","label":"Grupo Dataflux v. Atlas Global Group, L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"the jurisdiction of the court depends upon the state of things at the time of the action brought.","cite":"541 U.S. 567, 570"}]},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"589 U.S. 221","y":2020,"id":"2019/18-776","sc":1,"by":{"0":"8, 36, 37, 40, 44, 52","1":"36, 38"},"q":[{"src":"brief","b":0,"text":"can only be overcome by ‘clear and convincing evidence’ of congressional intent to preclude judicial review.","cite":"589 U.S. at 229"},{"src":"brief","b":1,"text":"[T]he presumption favoring judicial review of administrative action","cite":"589 U.S. 221, 229"},{"src":"opinion","who":"Justice Thomas, concurring","text":"`consolidate[d] judicial review of immigration proceedings into one action in the court of appeals.'","cite":"589 U. S. 221, 230"},{"src":"opinion","who":"Justice Thomas, concurring","text":"when a statutory provision `is reasonably susceptible to divergent interpretation, we adopt the reading that accords with traditional understandings and basic principles: that executive determinations generally are subject to judicial review.'","cite":"589 U. S., at 229"},{"src":"argument","who":"Justice Jackson","text":"And -- and haven't we also said in Guerrero-Lasprilla that there's a presumption of judicial review, that, you know, we not foreclose the possibility of judicial review over agency action unless there's clear and convincing evidence that Congress intended that result?"}]},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"by":{"0":"34"}},{"t":"case","label":"Hall v. United States","cite":"566 U.S. 506","y":2012,"id":"2011/10-875","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"it is not for us to rewrite the statute,","cite":"566 U.S. 506, 523"}]},{"t":"case","label":"Harrow v. Department of Defense","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"by":{"0":"18, 20, 21, 24, 25","1":"17-20, 22","2":"9, 10"},"q":[{"src":"brief","b":0,"text":"we now demand a ‘clear statement.’","cite":"601 U.S. at 489"},{"src":"brief","b":1,"text":"procedural requirements that Congress enacts to govern the litigation process","cite":"601 U.S. 480, 483"},{"src":"brief","b":1,"text":"statutory deadlines to appeal ‘from one Article III court to another.’","cite":"601 U.S. at 489"},{"src":"brief","b":2,"text":"‘no consequence’ [for] the jurisdictional issue.","cite":"601 U.S. at 485"}]},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"18, 19, 23, 26","1":"19, 21"},"q":[{"src":"brief","b":0,"text":"[not] ‘all mandatory prescriptions, however emphatic, are . . . properly typed jurisdictional.’","cite":"562 U.S. at 439"},{"src":"brief","b":0,"text":"predate this Court’s effort to ‘bring some discipline’ to the use of the term ‘jurisdictional.’","cite":"562 U.S. at 435"}]},{"t":"case","label":"Inestroza-Tosta v. Attorney General","cite":"105 F.4th 499","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/105/499/","by":{"0":"21, 42","1":"37"},"q":[{"src":"brief","b":0,"text":"No jurisdictional language is present in the [(b)(1)] provision even though Congress clearly provided for jurisdictional treatment elsewhere.","cite":"105 F.4th 499, 511"}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"8","1":"32"}},{"t":"case","label":"Janus v. State, County, and Municipal Employees","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Jean-Pierre v. U.S. Attorney General","cite":"500 F.3d 1315","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/500/1315/","by":{"0":"8"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"by":{"0":"22","2":"9, 10"},"q":[{"src":"argument","who":"Mr. Hammer","text":"As this Court recognized in John R. Sand & Gravel, abiding by the Court's statutory decision serves important system-wide reliance interests, promotes the overall stability and predictability of the law, and it's important -- particularly important here because just a year after Stone, Congress and IIRIRA further restricted the availability of judicial review."}]},{"t":"case","label":"Johnson v. Guzman Chavez","cite":"594 U.S. 523","y":2021,"id":"2020/19-897","sc":1,"by":{"0":"15, 16, 46, 47, 49–51","1":"6, 15, 16, 24, 37, 44-48","2":"13, 18, 19, 21"},"q":[{"src":"brief","b":1,"text":"the phrase ‘final order of removal’ as it is used in 8 U.S.C. § 1252(b)(1).","cite":"594 U.S. at 535 n.6"},{"src":"brief","b":1,"text":"physically remove[d] * * * from the United States.","cite":"594 U.S. at 528"},{"src":"opinion","who":"Justice Thomas, concurring","text":"does not depend in any way on the outcome of the withholding-only proceedings.","cite":"594 U. S., at 539"},{"src":"argument","who":"Mr. Bradley","text":"Therefore, we would expect -- not necessarily in every case -- but we would expect that, conceptually, administratively different \"final\" is different from \"final.\" And so that point, that Guzman Chavez pointed out, when detention can begin because one issue in the case has been resolved is different from the case point when everything is finished, when the agency has fully finished with its work."},{"src":"argument","who":"Justice Alito","text":"When it's a serious claim like that, it could sometimes take several months to even over a year. The dissent in Guzman Chavez pointed to some instances where they took multiple years, I believe."},{"src":"argument","who":"Justice Alito","text":"I also want to just point out, in -- in terms -- in terms of the -- any public safety concerns about giving this additional time or additional process to aggravated felons, it's important to bear in mind that they can be detained throughout the entirety of the agency proceedings, as well as subsequent judicial review proceedings. And this Court affirmed that power in Guzman Chavez."}]},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"by":{"0":"24"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"40, 44","1":"36","2":"24, 25"},"q":[{"src":"brief","b":0,"text":"‘wellsettled,’ . . . the Court assumes that ‘Congress legislates with knowledge of’ the presumption.","cite":"558 U.S. 233, 251–252"},{"src":"brief","b":0,"text":"consistently applied that interpretive guide to legislation regarding immigration, and particularly to questions concerning the preservation of federal-court jurisdiction.","cite":"558 U.S. at 251"},{"src":"brief","b":1,"text":"assumes that ‘Congress legislates with knowledge of ’","cite":"558 U.S. 233, 251-252"},{"src":"brief","b":2,"text":"Separation-of-powers concerns . . . caution us against reading legislation, absent clear statement, to place in executive hands authority to remove cases from the Judiciary’s domain.","cite":"558 U.S. at 237"}]},{"t":"case","label":"Lolong v. Gonzales","cite":"484 F.3d 1173","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/1173/","by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"eliminating the impediment to that order’s enforcement.","cite":"484 F.3d 1173, 1177"}]},{"t":"case","label":"Luna-Garcia v. Holder","cite":"777 F.3d 1182","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1182/","by":{"0":"33","1":"41"},"q":[{"src":"brief","b":0,"text":"not fully determined until the reasonable fear and withholding of removal proceedings are complete.","cite":"777 F.3d 1182, 1185"}]},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"Congress rarely intends to prevent courts from enforcing its directives to federal agencies.","cite":"575 U.S. 480, 486"}]},{"t":"case","label":"Martinez v. Garland","cite":"86 F.4th 561","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/86/561/","by":{"0":"12, 43, 49","1":"10-12, 14, 28, 37, 38, 41, 43, 47, 48"},"q":[{"src":"brief","b":1,"text":"the agency’s ‘final order’ for purposes of judicial review.","cite":"86 F.4th at 568"},{"src":"brief","b":1,"text":"[t]he 30-day deadline is mandatory and jurisdictional.","cite":"86 F.4th at 566"},{"src":"opinion","who":"Justice Thomas, concurring","text":"may not appeal [those] decision[s] to the BIA (or even to an immigration judge).","cite":"86 F. 4th 561, 568"}]},{"t":"case","label":"Mohawk Industries, Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"A ‘final decision’ is typically one ‘by which a district court disassociates itself from a case.’","cite":"558 U.S. 100, 106"}]},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"by":{"0":"6, 40"},"q":[{"src":"brief","b":0,"text":"has no discretion to deny [CAT] relief to a noncitizen who establishes his eligibility.","cite":"569 U.S. at 187, n.1"},{"src":"opinion","who":"Justice Thomas, concurring","text":"the Attorney General has no discretion to deny relief to a noncitizen who establishes his eligibility.","cite":"569 U. S. 184, 188, n. 1"}]},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"expressly refer to subject-matter jurisdiction or speak in jurisdictional terms.","cite":"577 U.S. 237, 246"}]},{"t":"case","label":"Nasrallah v. Barr","cite":"590 U.S. 573","y":2020,"id":"2019/18-1432","sc":1,"by":{"0":"3, 8, 9, 15, 28, 36, 41, 42, 44–46, 48, 52","1":"4, 6, 15, 24, 32, 34, 35, 40, 42-44, 47","2":"13"},"q":[{"src":"brief","b":0,"text":"a noncitizen’s various challenges arising from the removal proceeding must be ‘consolidated in a petition for review.’","cite":"590 U.S. at 580"},{"src":"brief","b":0,"text":"critical to determining whether the noncitizen is likely to be tortured if returned, it makes some sense that Congress would provide an opportunity for judicial review.","cite":"590 U.S. at 586"},{"src":"brief","b":1,"text":"a noncitizen’s various challenges arising from the removal proceeding must be ‘consolidated in a petition for review and considered by the courts of appeals.’","cite":"590 U.S. 573, 580"},{"src":"brief","b":1,"text":"the noncitizen still ‘may be removed at any time to another country where he or she is not likely to be tortured.’","cite":"590 U.S. at 582"},{"src":"opinion","who":"Justice Thomas, concurring","text":"[A] `fnal order of removal' is a fnal order `concluding that the alien is deportable or ordering deportation.'","cite":"590 U. S. 573, 579"},{"src":"opinion","who":"Justice Thomas, concurring","text":"CAT orders are not the same as fnal orders of removal.","cite":"590 U. S., at 582"},{"src":"opinion","who":"Justice Thomas, concurring","text":"a specifc grant of jurisdiction over CAT claims.","cite":"590 U. S., at 591"},{"src":"opinion","who":"Justice Thomas, concurring","text":"In other words, a fnal order of removal is required if a court is to review a CAT order at all.","cite":"590 U. S., at 592"},{"src":"argument","who":"Mr. Bradley","text":"The -- the Court -- the statute allows the Court to conduct review within 30 days of a final order from removal, but it also clearly says the Court has jurisdiction to review a CAT order as the Court explained in Nasrallah already."},{"src":"argument","who":"Mr. Bradley","text":"I think what Nasrallah teaches us, like -- certainly, is that it does not convert the -- a CAT order that says -- that -- that denies CAT relief is not converting the final order into something else, except from the timing of it and what gets decided is affecting the finality, because as we explained in the brief, and I believe the government agrees, where you can be sent is something that remains to be decided."},{"src":"argument","who":"Mr. Bradley","text":"I -- I think you have it exactly right, that -- that analogy. And Nasrallah was familiar with that analogy, of course."}]},{"t":"case","label":"National Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"by":{"0":"45"}},{"t":"case","label":"Natural Resources Defense Council, Inc. v. NRC","cite":"680 F.2d 810","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/680/810/","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"[I]n an adjudication a final order is one that disposes of all issues as to all parties.","cite":"680 F.2d 810, 815"}]},{"t":"case","label":"Neirbo Co. v. Bethlehem Shipbuilding Corp.","cite":"308 U.S. 165","y":1939,"id":"scdb/1939-030","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"basic difference [from] the court’s power.","cite":"308 U.S. 165, 168"}]},{"t":"case","label":"Ogbudimkpa v. Ashcroft","cite":"342 F.3d 207","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/342/207/","by":{"0":"8"}},{"t":"case","label":"Owino v. Holder","cite":"575 F.3d 956","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/956/","by":{"0":"8"}},{"t":"case","label":"Port of Boston Marine Terminal Assn. v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"by":{"0":"30, 31, 34","2":"3"},"q":[{"src":"brief","b":0,"text":"relevant considerations in determining finality [is] whether the process of administrative decisionmaking has reached a stage where judicial review will not disrupt the orderly process of adjudication.","cite":"400 U.S. 62, 71"},{"src":"brief","b":2,"text":"will not disrupt the orderly process of adjudication.","cite":"400 U.S. 62, 71"}]},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"by":{"0":"7, 26","2":"10"},"q":[{"src":"brief","b":0,"text":"repealed the old judicial-review scheme . . . and instituted a new (and significantly more restrictive) one.","cite":"525 U.S. 471, 475"},{"src":"brief","b":2,"text":"repealed the old judicial-review scheme . . . and instituted a new . . . one.","cite":"525 U.S. 471, 475"}]},{"t":"case","label":"Rodriguez-Roman v. INS","cite":"98 F.3d 416","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/98/416/","by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"in an area where administrative decisions can mean the difference between freedom and oppression and, quite possibly, life and death.","cite":"98 F.3d 416, 432"}]},{"t":"case","label":"Saint Fort v. Ashcroft","cite":"329 F.3d 191","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/329/191/","by":{"0":"8"}},{"t":"case","label":"Sanabria Morales v. Barr","cite":"967 F.3d 15","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/967/15/","by":{"0":"43"}},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"[U]nless otherwise defined, words will be interpreted as taking their ordinary, contemporary, common meaning.’","cite":"571 U.S. 220, 227"}]},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"by":{"0":"12, 13, 17, 18, 20, 21, 24, 25, 27, 52","1":"10, 13, 18, 21-23, 36","2":"7, 8, 12"},"q":[{"src":"brief","b":0,"text":"treat a rule as jurisdictional ‘only if Congress clearly states that it is.’","cite":"598 U.S. 411, 416"},{"src":"brief","b":0,"text":"treat[s] a rule as jurisdictional ‘only if Congress clearly states that it is.’","cite":"598 U.S. at 416"},{"src":"brief","b":1,"text":"sua sponte, even in the face of a litigant’s forfeiture or waiver.","cite":"598 U.S. 411, 416"},{"src":"brief","b":1,"text":"‘some discipline to the use of th[e] term’ ‘jurisdictional.’","cite":"598 U.S. at 421"},{"src":"argument","who":"Mr. Bradley","text":"Regarding jurisdiction, Santos-Zacaria already explained that Stone was not a holding on that point. The Court should adhere to what it said there."},{"src":"argument","who":"Mr. Hammer","text":"And Santos-Zacaria, which was focused on the INA's separate exhaustion provision, didn't disturb the deadline's jurisdictional status. The Fourth Circuit also correctly held that Mr."},{"src":"argument","who":"Justice Jackson","text":"I don't understand your distinguishing Santos-Zacaria. It seems to me that if Stone's jurisdictional language was binding in the way that you claim, that it would have governed the outcome in that case as well."}]},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"by":{"0":"25"}},{"t":"case","label":"Sebelius v. Auburn Regional Medical Center","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"20","1":"18"},"q":[{"src":"brief","b":0,"text":"[a] requirement we would otherwise classify as nonjurisdictional . . . does not become jurisdictional simply because it is placed in a section of a statute that also contains jurisdictional provisions.","cite":"568 U.S. 145, 155"}]},{"t":"case","label":"Smith v. Berryhill","cite":"587 U.S. 471","y":2019,"id":"2018/17-1606","sc":1,"by":{"0":"30, 40","1":"30"},"q":[{"src":"brief","b":0,"text":"[T]he burden for rebutting it is heavy,","cite":"587 U.S. at 483"},{"src":"brief","b":1,"text":"clearly denotes some kind of terminal event.","cite":"587 U.S. 471, 479"},{"src":"opinion","who":"Justice Thomas, concurring","text":"clearly denotes some Sotomayor, J., dissenting in part kind of terminal event.","cite":"587 U. S. 471, 479"}]},{"t":"case","label":"Solano-Chicas v. Gonzales","cite":"440 F.3d 1050","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/1050/","by":{"0":"32"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"by":{"0":"39, 50","2":"18"},"q":[{"src":"brief","b":0,"text":"[W]here [a] document has used one term in one place, and a materially different term in another, the presumption is that the different term denotes a different idea.","cite":"596 U.S. 450, 457–458"}]},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"by":{"0":"13, 21, 22–27, 34, 35, 37, 38","1":"3, 10, 13, 17, 22, 23, 32","2":"1–9, 11, 12"},"q":[{"src":"brief","b":1,"text":"is ‘jurisdictional in nature and must be construed with strict fidelity to [its] terms.’","cite":"514 U.S. at 405"},{"src":"argument","who":"Mr. Bradley","text":"Regarding jurisdiction, Santos-Zacaria already explained that Stone was not a holding on that point. The Court should adhere to what it said there."},{"src":"argument","who":"Chief Justice Roberts","text":"Well, I mean, there is the fact that they applied equitable tolling in the prior -- the -- the -- the -- the -- the -- the Stone -- case and said equitable tolling was not available, which sounds like something you would say if you're dealing with a jurisdictional provision."},{"src":"argument","who":"Mr. Bradley","text":"But the second thing is to go back to your observations about Stone, whether the equitable tolling could be available is in -- Stone's an excellent example of something that mentioned that in passing and made no difference to the case."}]},{"t":"case","label":"Tadeo v. Garland","cite":"2024 WL 2780230","y":2024,"court":"5th Cir. May 30","by":{"0":"43"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"by":{"0":"34, 35"},"q":[{"src":"brief","b":0,"text":"When a statutory term is ‘obviously transplanted from another legal source,’ it ‘brings the old soil with it.’","cite":"587 U.S. 554, 560"}]},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"17, 19, 21","1":"18-21"},"q":[{"src":"brief","b":0,"text":"Time and again, [the Court] ha[s] described filing deadlines as ‘quintessential claim-processing rules,’ which ‘seek to promote the orderly progress of litigation,’ but do not deprive a court of authority to hear a case.","cite":"575 U.S. 402, 410"},{"src":"brief","b":0,"text":"‘reads like an ordinary, run-of-the-mill statute of limitations,’ spelling out a litigant’s filing obligations without restricting a court’s authority.","cite":"575 U.S. at 411"},{"src":"brief","b":1,"text":"traditional tools of statutory construction must plainly show that Congress imbued [the rule] with jurisdictional consequences.","cite":"575 U.S. 402, 410"},{"src":"brief","b":1,"text":"described filing deadlines as ‘quintessential claimprocessing rules,’ which ‘seek to promote the orderly progress of litigation,’ but do not deprive a court of authority to hear a case.","cite":"575 U.S. at 410"}]},{"t":"case","label":"Weyerhaeuser Co. v. United States Fish and Wildlife Serv.","cite":"586 U.S. 9","y":2018,"id":"2018/17-71","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"the sort of routine dispute that federal courts regularly review.","cite":"586 U.S. at 23"}]},{"t":"case","label":"Whitman v. Am. Trucking Assns.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"0":"30"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"by":{"0":"18, 22–24, 26","1":"19, 23","2":"2, 7, 8, 11"},"q":[{"src":"brief","b":0,"text":"[C]ourts, including this Court, have more than occasionally misused the term ‘jurisdictional’ to refer to nonjurisdictional prescriptions.","cite":"598 U.S. at 159"},{"src":"brief","b":0,"text":"stand in for a ruling of this Court.","cite":"598 U.S. at 165"},{"src":"brief","b":2,"text":"if the prior decision addressed whether a provision . . . truly operates as a limit on a court’s subject-matter jurisdiction.","cite":"598 U.S. at 160"},{"src":"argument","who":"Mr. Hammer","text":"That's the exact opposite of what happened in Beggerly, the Court that this -- the case that this Court analyzed in Wilkins and said didn't count as a definitive jurisdictional precedent."}]},{"t":"case","label":"Zavaleta-Policiano v. Sessions","cite":"873 F.3d 241","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/873/241/","by":{"0":"41"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)","(a)(3)","(a)(47)(A)","(a)(47)(B)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"2, 2, 3, 25, 26, 42, 4, 11, 14, 26-30, 39, 43","2":"16"},"q":[{"src":"brief","b":1,"text":"concluding that the alien is deportable or ordering deportation.","cite":"8 U.S.C. 1101(a)(47)(A)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"concluding that the alien is deportable or ordering deportation.","cite":"8 U. S. C. § 1101(a)(47)(A)"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","by":{"0":"20"}},{"t":"law","label":"Foreign Affairs Reform and Restructuring Act, Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"6, 8, 28, 40, 41","1":"5"}},{"t":"law","label":"Illegal Immigration Reform and Immigrant Responsibility Act, Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"6, 26, 34, 35, 37","1":"4"}},{"t":"law","label":"REAL ID Act, Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"8","1":"8"}},{"t":"reg","label":"8 C.F.R. § 238.1","url":"https://www.ecfr.gov/current/title-8/section-238.1","subs":["(b)"],"by":{"0":"4"}},{"t":"reg","label":"64 Fed. Reg. 8,478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"0":"6"}},{"t":"case","label":"Barton v. Barr","cite":"590 U.S. 222","y":2020,"id":"2019/18-725","sc":1,"by":{"1":"2"}},{"t":"case","label":"Bhaktibhai-Patel v. Garland","cite":"32 F.4th 180","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/32/180/","by":{"1":"11, 28, 38, 41, 43, 47"},"q":[{"src":"brief","b":1,"text":"the final stage of agency review available as of right to aliens.","cite":"32 F.4th at 192, 194"},{"src":"opinion","who":"Justice Thomas, concurring","text":"may not appeal [those] decision[s] to the BIA (or even to an immigration judge).","cite":"32 F. 4th 180, 192"}]},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"by":{"1":"3"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"by":{"1":"31, 33, 45"},"q":[{"src":"brief","b":1,"text":"disassociates itself from the case, leaving nothing to be done at the [tribunal] of first instance save execution of the judgment.","cite":"537 U.S. at 527"},{"src":"brief","b":1,"text":"[f ]inality is variously defined; like many legal terms, its precise meaning depends on context.","cite":"537 U.S. at 527"},{"src":"opinion","who":"Justice Thomas, concurring","text":"when the district court disassociates itself from the case, leaving nothing to be done at the court of frst instance save execution of the judgment.","cite":"537 U. S. 522, 527"},{"src":"opinion","who":"Justice Thomas, concurring","text":"Finality is variously defned; like many legal terms, its precise meaning depends on context.","cite":"537 U. S., at 527"}]},{"t":"case","label":"DHS v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/103/","sc":1,"by":{"1":"26"}},{"t":"case","label":"Digital Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"by":{"1":"31"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"583 U.S. 149","y":2018,"id":"2017/16-1276","sc":1,"by":{"1":"27"}},{"t":"case","label":"Environmental Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"by":{"1":"29"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"by":{"1":"27, 28"},"q":[{"src":"brief","b":1,"text":"explicitly insulate[d] [reinstatement] orders from review, and generally foreclose[d] discretionary relief from the terms of the reinstated order.","cite":"548 U.S. at 35"}]},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"by":{"1":"41"}},{"t":"case","label":"Gonzalez v. Chertoff","cite":"454 F.3d 813","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/813/","by":{"1":"28"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"is ‘reasonably susceptible to divergent interpretation, [the Court] adopt[s] the reading that accords with traditional understandings and basic principles: that executive determinations generally are subject to judicial review.’","cite":"515 U.S. 417, 434"}]},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"by":{"1":"20"}},{"t":"case","label":"Heikkila v. Barber","cite":"345 U.S. 229","y":1953,"id":"scdb/1952-068","sc":1,"by":{"1":"2"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"1":"5"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"1":"5","2":"12"},"q":[{"src":"brief","b":2,"text":"reenacts [the relevant provision] without change.","cite":"543 U.S. 335, 349"}]},{"t":"case","label":"Jimenez-Morales v. U.S. Attorney Gen.","cite":"821 F.3d 1307","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1307/","by":{"1":"41"}},{"t":"case","label":"Kolov v. Garland","cite":"78 F.4th 911","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/78/911/","by":{"1":"32, 38, 39, 46"},"q":[{"src":"brief","b":1,"text":"by barring removal to the specific country that the order lists.","cite":"78 F.4th 911, 928"},{"src":"brief","b":1,"text":"In ordinary removal proceedings [under Section 1229a], the Board often affirms a conclusion that an immigrant is removable but remands for more proceedings on the immigrant’s claims for withholding of removal under § 1231(b)(3)(A) or CAT.","cite":"78 F.4th at 924"},{"src":"opinion","who":"Justice Thomas, concurring","text":"an immigration judge's removability fnding but remand[s] for further consideration of withholding claims","cite":"78 F. 4th, at 927"}]},{"t":"case","label":"Lawson v. Suwannee Fruit & S.S. Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"by":{"1":"30"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"Congress intended a difference in meaning.","cite":"573 U.S. 351, 358"}]},{"t":"case","label":"McLish v. Roff","cite":"141 U.S. 661","y":1891,"id":"scdb/1891-036","sc":1,"by":{"1":"31"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"582 U.S. 23","y":2017,"id":"2016/15-457","sc":1,"by":{"1":"31, 32, 35"},"q":[{"src":"brief","b":1,"text":"‘the whole case and every matter in controversy in it [must be] decided in a single appeal.’","cite":"582 U.S. 23, 36"}]},{"t":"case","label":"Nielsen v. Preap","cite":"586 U.S. 392","y":2019,"id":"2018/16-1363","sc":1,"by":{"1":"2"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"by":{"1":"24","2":"5, 9"},"q":[{"src":"brief","b":2,"text":"[t]hose earlier statements did not necessarily signify that the rules at issue were formally ‘jurisdictional.’","cite":"586 U.S. at 192, n.3"}]},{"t":"case","label":"Ortiz-Alfaro v. Holder","cite":"694 F.3d 955","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/955/","by":{"1":"41"}},{"t":"case","label":"Osuna-Gutierrez v. Johnson","cite":"838 F.3d 1030","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/1030/","by":{"1":"28"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"by":{"1":"40"},"q":[{"src":"argument","who":"Mr. Hammer","text":"So under a 1978 Board decision called Matter of Patel, when the Board remands a case, it's a general or plenary remand that allows reconsideration of any issue on remand, unless the Board --"}]},{"t":"case","label":"Ponce-Osorio v. Johnson","cite":"824 F.3d 502","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/502/","by":{"1":"41"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"1":"29, 30"},"q":[{"src":"brief","b":1,"text":"the specific context in which that language is used, and the broader context of the statute as a whole.","cite":"519 U.S. at 341"}]},{"t":"case","label":"Salgado v. Garland","cite":"69 F.4th 179","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/69/179/","by":{"1":"22, 23"},"q":[{"src":"brief","b":1,"text":"is ‘jurisdictional in nature and must be construed with strict fidelity to [its] terms.’","cite":"69 F.4th 179, 181"}]},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"by":{"1":"3, 45, 46"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"1":"14, 29, 30, 48","2":"16"},"q":[{"src":"brief","b":1,"text":"[T]he presumption of consistent usage ‘readily yields’ to context, and a statutory term—even one defined in the statute—‘may take on distinct characters from association with distinct statutory objects.’","cite":"573 U.S. at 320"},{"src":"brief","b":2,"text":"[A] statutory term—even one defined in the statute—may take on distinct characters","cite":"573 U.S. 302, 320"}]},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"13"}},{"t":"law","label":"Pub. L. No. 87-301","url":"https://www.govinfo.gov/link/statute/75/651","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"3"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(a)(1964)","(a)(1)(1964)","(a)(1)"],"by":{"1":"3, 3, 22, 23"},"q":[{"src":"brief","b":1,"text":"not later than six months from the date of the final deportation order,","cite":"8 U.S.C. 1105a(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(h)"],"by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(e)"],"by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/8/1228","subs":["(b)","(b)(3)","(b)(5)","(c)"],"stext":{"head":"§1228. Expedited removal of aliens convicted of committing aggravated felonies","paras":[[0,"(a) Removal of criminal aliens"],[0,"(1) In general"],[1,"The Attorney General shall provide for the availability of special removal proceedings at certain Federal, State, and local correctional facilities for aliens convicted of any criminal offense covered in section 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to the date of their commission, otherwise covered by section 1227(a)(2)(A)(i) of this title. Such proceedings shall be conducted in conformity with section 1229a of this title (except as otherwise provided in this section), and in a manner which eliminates the need for additional detention at any processing center of the Service and in a manner which assures expeditious removal following the end of the alien's incarceration for the underlying sentence. Nothing in this section shall be construed to create any substantive or procedural right or benefit that is legally enforceable by any party against the United States or its agencies or officers or any other person."],[0,"(2) Implementation"],[1,"With respect to an alien convicted of an aggravated felony who is taken into custody by the Attorney General pursuant to section 1226(c) of this title, the Attorney General shall, to the maximum extent practicable, detain any such felon at a facility at which other such aliens are detained. In the selection of such facility, the Attorney General shall make reasonable efforts to ensure that the alien's access to counsel and right to counsel under section 1362 of this title are not impaired."],[0,"(3) Expedited proceedings"],[1,"(A) Notwithstanding any other provision of law, the Attorney General shall provide for the initiation and, to the extent possible, the completion of removal proceedings, and any administrative appeals thereof, in the case of any alien convicted of an aggravated felony before the alien's release from incarceration for the underlying aggravated felony."],[1,"(B) Nothing in this section shall be construed as requiring the Attorney General to effect the removal of any alien sentenced to actual incarceration, before release from the penitentiary or correctional institution where such alien is confined."],[0,"(4) Review"],[1,"(A) The Attorney General shall review and evaluate removal proceedings conducted under this section."],[1,"(B) The Comptroller General shall monitor, review, and evaluate removal proceedings conducted under this section. Within 18 months after the effective date of this section, the Comptroller General shall submit a report to such Committees concerning the extent to which removal proceedings conducted under this section may adversely affect the ability of such aliens to contest removal effectively."],[0,"(b) Removal of aliens who are not permanent residents"],[0,"(1) The Attorney General may, in the case of an alien described in paragraph (2), determine the deportability of such alien under section 1227(a)(2)(A)(iii) of this title (relating to conviction of an aggravated felony) and issue an order of removal pursuant to the procedures set forth in this subsection or section 1229a of this title."],[0,"(2) An alien is described in this paragraph if the alien—"],[1,"(A) was not lawfully admitted for permanent residence at the time at which proceedings under this section commenced; or"],[1,"(B) had permanent resident status on a conditional basis (as described in section 1186a of this title) at the time that proceedings under this section commenced."],[0,"(3) The Attorney General may not execute any order described in paragraph (1) until 14 calendar days have passed from the date that such order was issued, unless waived by the alien, in order that the alien has an opportunity to apply for judicial review under section 1252 of this title."],[0,"(4) Proceedings before the Attorney General under this subsection shall be in accordance with such regulations as the Attorney General shall prescribe. The Attorney General shall provide that—"],[1,"(A) the alien is given reasonable notice of the charges and of the opportunity described in subparagraph (C);"],[1,"(B) the alien shall have the privilege of being represented (at no expense to the government) by such counsel, authorized to practice in such proceedings, as the alien shall choose;"],[1,"(C) the alien has a reasonable opportunity to inspect the evidence and rebut the charges;"],[1,"(D) a determination is made for the record that the individual upon whom the notice for the proceeding under this section is served (either in person or by mail) is, in fact, the alien named in such notice;"],[1,"(E) a record is maintained for judicial review; and"],[1,"(F) the final order of removal is not adjudicated by the same person who issues the charges."],[0,"(5) No alien described in this section shall be eligible for any relief from removal that the Attorney General may grant in the Attorney General's discretion."],[0,"(c) 1 Presumption of deportability"],[0,"An alien convicted of an aggravated felony shall be conclusively presumed to be deportable from the United States."],[0,"(c) 1 Judicial removal"],[0,"(1) Authority"],[1,"Notwithstanding any other provision of this chapter, a United States district court shall have jurisdiction to enter a judicial order of removal at the time of sentencing against an alien who is deportable, if such an order has been requested by the United States Attorney with the concurrence of the Commissioner and if the court chooses to exercise such jurisdiction."],[0,"(2) Procedure"],[1,"(A) The United States Attorney shall file with the United States district court, and serve upon the defendant and the Service, prior to commencement of the trial or entry of a guilty plea a notice of intent to request judicial removal."],[1,"(B) Notwithstanding section 1252b 2 of this title, the United States Attorney, with the concurrence of the Commissioner, shall file at least 30 days prior to the date set for sentencing a charge containing factual allegations regarding the alienage of the defendant and identifying the crime or crimes which make the defendant deportable under section 1227(a)(2)(A) of this title."],[1,"(C) If the court determines that the defendant has presented substantial evidence to establish prima facie eligibility for relief from removal under this chapter, the Commissioner shall provide the court with a recommendation and report regarding the alien's eligibility for relief. The court shall either grant or deny the relief sought."],[1,"(D)(i) The alien shall have a reasonable opportunity to examine the evidence against him or her, to present evidence on his or her own behalf, and to cross-examine witnesses presented by the Government."],[1,"(ii) The court, for the purposes of determining whether to enter an order described in paragraph (1), shall only consider evidence that would be admissible in proceedings conducted pursuant to section 1229a of this title."],[1,"(iii) Nothing in this subsection shall limit the information a court of the United States may receive or consider for the purposes of imposing an appropriate sentence."],[1,"(iv) The court may order the alien removed if the Attorney General demonstrates that the alien is deportable under this chapter."],[0,"(3) Notice, appeal, and execution of judicial order of removal"],[1,"(A)(i) A judicial order of removal or denial of such order may be appealed by either party to the court of appeals for the circuit in which the district court is located."],[1,"(ii) Except as provided in clause (iii), such appeal shall be considered consistent with the requirements described in section 1252 of this title."],[1,"(iii) Upon execution by the defendant of a valid waiver of the right to appeal the conviction on which the order of removal is based, the expiration of the period described in section 1252(b)(1) of this title, or the final dismissal of an appeal from such conviction, the order of removal shall become final and shall be executed at the end of the prison term in accordance with the terms of the order. If the conviction is reversed on direct appeal, the order entered pursuant to this section shall be void."],[1,"(B) As soon as is practicable after entry of a judicial order of removal, the Commissioner shall provide the defendant with written notice of the order of removal, which shall designate the defendant's country of choice for removal and any alternate country pursuant to section 1253(a) 2 of this title."],[0,"(4) Denial of judicial order"],[1,"Denial of a request for a judicial order of removal shall not preclude the Attorney General from initiating removal proceedings pursuant to section 1229a of this title upon the same ground of deportability or upon any other ground of deportability provided under section 1227(a) of this title."],[0,"(5) Stipulated judicial order of removal"],[1,"The United States Attorney, with the concurrence of the Commissioner, may, pursuant to Federal Rule of Criminal Procedure 11, enter into a plea agreement which calls for the alien, who is deportable under this chapter, to waive the right to notice and a hearing under this section, and stipulate to the entry of a judicial order of removal from the United States as a condition of the plea agreement or as a condition of probation or supervised release, or both. The United States district court, in both felony and misdemeanor cases, and a United States magistrate judge in misdemeanor cases, may accept such a stipulation and shall have jurisdiction to enter a judicial order of removal pursuant to the terms of such stipulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1228?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6-8, 12, 14-16, 24-30, 32, 7, 26, 6, 6"},"q":[{"src":"brief","b":1,"text":"relief from removal that the Attorney General may grant in the Attorney General’s discretion.","cite":"8 U.S.C. 1228(b)(5)"},{"src":"argument","who":"Justice Gorsuch","text":"McDOWELL: So I think under his position, I think the CAT order in this case would be unreviewable because Petitioner didn't file the petition for review within 30 days of the Section 1228 removal."},{"src":"argument","who":"Justice Alito","text":"But here, and as -- as is usually the case under the regulations, these claims are brought contemporaneously with the entry of the Section 1228 removal order."}]},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)"],"by":{"1":"26, 30, 32, 38, 43, 26"},"q":[{"src":"brief","b":1,"text":"proceedings for deciding the inadmissibility or deportability of an alien,","cite":"8 U.S.C. 1229a(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)","(a)(1)","(a)(1)(B)(i)","(a)(2)","(a)(5)","(b)(1)","(b)(2)","(b)(3)","(b)(3)(B)","(b)(3)(C)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"by":{"1":"45-47, 16, 45, 46, 16, 44, 46, 47, 6, 7, 10, 11, 14, 15, 27, 28, 37, 39-41, 44, 5, 5, 5, 9, 34"},"q":[{"src":"brief","b":1,"text":"[t]he date the order of removal becomes administratively final.","cite":"8 U.S.C. 1231(a)(1)(B)(i)"},{"src":"brief","b":1,"text":"[d]etention and removal of aliens ordered removed,","cite":"8 U.S.C. 1231"},{"src":"argument","who":"Mr. Hammer","text":"Section 1228(b), the INA's statutory definition of a final order of removal, and Section 1231 all confirm that a final administrative removal order is, as its name indicates, final when issued."},{"src":"argument","who":"Mr. Hammer","text":"Riley was ordered removed to Jamaica or any alternate country proscribed by Section 1231. So there wasn't any need -- there wouldn't be any need for amendment."},{"src":"argument","who":"Mr. Hammer","text":"But if you disagree with me on that, I think Section 1228(b) itself answers this question, and it's strongly supported by Section 1231 and what this Court said about administrative finality in Guzman Chavez."}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(C)","(a)(4)","(b)","(b)(1)","(b)(2)","(b)(3)(A)","(b)(3)(C)","(b)(4)","(b)(6)","(b)(9)","(d)(1)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, 8, 31, 36, 45, 47, 48, 2, 4, 31, 40, 42, 43, 8, 34, 40, 43, 21, 2, 4, 10-17, 20-26, 30, 32, 34-37, 39, 40, 42-46, 48, 21, 21, 22, 34, 40, 32, 4, 15, 31, 32, 34, 43, 46, 23, 32, 27"},"q":[{"src":"brief","b":1,"text":"[ j]udicial review of a final order of removal.","cite":"8 U.S.C. 1252(a)(1)"},{"src":"brief","b":1,"text":"not later than 30 days after the date of the final order of removal.","cite":"8 U.S.C. 1252(b)(1)"},{"src":"opinion","who":"Justice Thomas, concurring","text":"[j]udicial review of a fnal order of removal.","cite":"8 U. S. C. § 1252(a)(1)"},{"src":"argument","who":"Mr. Hammer","text":"I take Santos-Zacaria -- Zacaria to be responding to the government's argument in that case that the entirety of the INA's judicial review provision, everything in Section 1252, was jurisdictional."},{"src":"argument","who":"Mr. Hammer","text":"So Section 1228(b)(4)(F) calls an order entered under this -- under that subsection a final order of removal, using exactly the same language that Section 1252 does itself."},{"src":"argument","who":"Mr. Hammer","text":"I think there's a strong presumption that also governs finality in Section 1252. And we can see evidence of that in the statutory text in Section 1252(b)(8)(A), which cross-references Section 1231 and uses the words \"a final order of removal\" to indicate the beginning of the removal period under Section 1231."}]},{"t":"usc","label":"8 U.S.C. § 1252a","url":"https://www.law.cornell.edu/uscode/text/8/1252a","subs":["(a)(3)(A)(1994)"],"by":{"1":"27"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(a)(1)","(a)(1)(B)"],"stext":{"head":"§1253. Penalties related to removal","paras":[[0,"(a) Penalty for failure to depart"],[0,"(1) In general"],[1,"Any alien against whom a final order of removal is outstanding by reason of being a member of any of the classes described in section 1227(a) of this title, who—"],[2,"(A) willfully fails or refuses to depart from the United States within a period of 90 days from the date of the final order of removal under administrative processes, or if judicial review is had, then from the date of the final order of the court,"],[2,"(B) willfully fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure,"],[2,"(C) connives or conspires, or takes any other action, designed to prevent or hamper or with the purpose of preventing or hampering the alien's departure pursuant to such, or"],[2,"(D) willfully fails or refuses to present himself or herself for removal at the time and place required by the Attorney General pursuant to such order,"],[1,"shall be fined under title 18, or imprisoned not more than four years (or 10 years if the alien is a member of any of the classes described in paragraph (1)(E), (2), (3), or (4) of section 1227(a) of this title), or both."],[0,"(2) Exception"],[1,"It is not a violation of paragraph (1) to take any proper steps for the purpose of securing cancellation of or exemption from such order of removal or for the purpose of securing the alien's release from incarceration or custody."],[0,"(3) Suspension"],[1,"The court may for good cause suspend the sentence of an alien under this subsection and order the alien's release under such conditions as the court may prescribe. In determining whether good cause has been shown to justify releasing the alien, the court shall take into account such factors as—"],[2,"(A) the age, health, and period of detention of the alien;"],[2,"(B) the effect of the alien's release upon the national security and public peace or safety;"],[2,"(C) the likelihood of the alien's resuming or following a course of conduct which made or would make the alien deportable;"],[2,"(D) the character of the efforts made by such alien himself and by representatives of the country or countries to which the alien's removal is directed to expedite the alien's departure from the United States;"],[2,"(E) the reason for the inability of the Government of the United States to secure passports, other travel documents, or removal facilities from the country or countries to which the alien has been ordered removed; and"],[2,"(F) the eligibility of the alien for discretionary relief under the immigration laws."],[0,"(b) Willful failure to comply with terms of release under supervision"],[0,"An alien who shall willfully fail to comply with regulations or requirements issued pursuant to section 1231(a)(3) of this title or knowingly give false information in response to an inquiry under such section shall be fined not more than $1,000 or imprisoned for not more than one year, or both."],[0,"(c) Penalties relating to vessels and aircraft"],[0,"(1) Civil penalties"],[0,"(A) Failure to carry out certain orders"],[2,"If the Attorney General is satisfied that a person has violated subsection (d) or (e) of section 1231 of this title, the person shall pay to the Commissioner the sum of $2,000 for each violation."],[0,"(B) Failure to remove alien stowaways"],[2,"If the Attorney General is satisfied that a person has failed to remove an alien stowaway as required under section 1231(d)(2) of this title, the person shall pay to the Commissioner the sum of $5,000 for each alien stowaway not removed."],[0,"(C) No compromise"],[2,"The Attorney General may not compromise the amount of such penalty under this paragraph."],[0,"(2) Clearing vessels and aircraft"],[0,"(A) Clearance before decision on liability"],[2,"A vessel or aircraft may be granted clearance before a decision on liability is made under paragraph (1) only if a bond approved by the Attorney General or an amount sufficient to pay the civil penalty is deposited with the Commissioner."],[0,"(B) Prohibition on clearance while penalty unpaid"],[2,"A vessel or aircraft may not be granted clearance if a civil penalty imposed under paragraph (1) is not paid."],[0,"(d) Discontinuing granting visas to nationals of country denying or delaying accepting alien"],[0,"On being notified by the Attorney General that the government of a foreign country denies or unreasonably delays accepting an alien who is a citizen, subject, national, or resident of that country after the Attorney General asks whether the government will accept the alien under this section, the Secretary of State shall order consular officers in that foreign country to discontinue granting immigrant visas or nonimmigrant visas, or both, to citizens, subjects, nationals, and residents of that country until the Attorney General notifies the Secretary that the country has accepted the alien."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1253?type=usc&year=mostrecent&link-type=html"},"by":{"1":"34, 34"},"q":[{"src":"brief","b":1,"text":"willfully fail or refuse[] to make timely application in good faith for travel or other documents necessary to [their] departure.","cite":"8 U.S.C. 1253(a)(1)(B)"}]},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)(1)"],"stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"within 60 days after the Board issues notice of the final order or decision.","cite":"5 U.S.C. 7703(b)(1)(A)"}]},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"tort claim against the United States shall be forever barred unless it is presented [to the agency] within two years,","cite":"28 U.S.C. 2401(b)"}]},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(g)"],"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"shall be barred unless it is commenced within twelve years of the date upon which it accrued,","cite":"28 U.S.C. 2409a(g)"}]},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)"],"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"shall file a notice of appeal * * * within 120 days,","cite":"38 U.S.C. 7266(a)"}]},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(d)"],"by":{"1":"32"}},{"t":"case","label":"Arkansas Game & Fish Comm’n v. United States","cite":"568 U.S. 23","y":2012,"id":"2012/11-597","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"resist[s] reading a single sentence unnecessary to the decision as having done so much work.","cite":"568 U.S. 23, 35"}]},{"t":"case","label":"Cohens v. Virginia","cite":"6 Wheat. 264","y":1821,"url":"https://www.courtlistener.com/c/Wheat./6/264/","by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"may be respected, but ought not to control.","cite":"6 Wheat. 264, 399"}]},{"t":"case","label":"Fourco Glass Co. v. Transmirra Products Corp.","cite":"353 U.S. 222","y":1957,"id":"1956/310","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"no changes of law or policy are to be presumed from changes of language in the [1948] revision unless an intent to make such changes is clearly expressed.","cite":"353 U.S. 222, 227"}]},{"t":"case","label":"Fulton v. Philadelphia","cite":"593 U.S. 522","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/522/","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"[a] title or heading should never be allowed to override the plain words of a text.","cite":"593 U.S. 522, 536"}]},{"t":"case","label":"Goldman Sachs Group, Inc. v. Arkansas Teachers Retirement System","cite":"594 U.S. 113","y":2021,"id":"2020/20-222","sc":1,"by":{"2":"18"}},{"t":"case","label":"ICC v. Locomotive Engineers","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"by":{"2":"4, 5, 19"},"q":[{"src":"opinion","who":"Justice Thomas, concurring","text":"[t]his would seem to mean that the pendency of reconsideration motions does not render [agency] orders nonfnal for pur- Page Proof Pending Publication poses of triggering the Hobbs Act limitations period.","cite":"482 U. S. 270, 284"}]},{"t":"case","label":"(iii) Cases—Continued Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"url":"https://supreme.justia.com/cases/federal/us/576/446/","sc":1,"by":{"2":"11"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"by":{"2":"12"}},{"t":"case","label":"Missouri v. Jenkins","cite":"495 U.S. 33","y":1990,"id":"1989/88-1150","sc":1,"by":{"2":"4"}},{"t":"case","label":"Pace v. DiGuglielmo","cite":"544 U.S. 408","y":2005,"id":"2004/03-9627","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"some extraordinary circumstance [that] stood in his way.","cite":"544 U.S. 408, 418"}]},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"[T]he opposite is true in cases . . . involving procedural and evidentiary rules,","cite":"501 U.S. 808, 828"}]},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2020,"id":"2015/15-339","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"[w]hen Congress amends legislation, courts must ‘presume it intends [the change] to have real and substantial effect.’","cite":"578 U.S. 632, 641– 42"}]},{"t":"case","label":"TikTok Inc. v. Garland","cite":"145 S. Ct. 57","y":2025,"id":"2024/24-656","sc":1,"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"need not address all aspects of a problem in one fell swoop,","cite":"145 S. Ct. 57, 70"}]},{"t":"case","label":"United States v. Dieter","cite":"429 U.S. 6","y":1976,"id":"1976/75-1547","sc":1,"by":{"2":"4"}},{"t":"case","label":"United States v. Ibarra","cite":"502 U.S. 1","y":1991,"id":"1991/90-1713","sc":1,"by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"2":"21"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"12"}},{"t":"reg","label":"8 C.F.R. § 208.5","url":"https://www.ecfr.gov/current/title-8/section-208.5","subs":["(a)"],"by":{"2":"15"}}]};